import subprocess, re
files=['internal/api/handlers_test.go','pkg/api/metrics_spec_trace.go','scripts/tick-closeout.sh','web/js/submit.js']
def markers(rev):
    out={}
    for f in files:
        try:
            txt=subprocess.run(['git','show',f'{rev}:{f}'],capture_output=True,text=True).stdout
        except Exception: continue
        for line in txt.splitlines():
            if 'ch:trace' in line:
                m=re.search(r'ch:trace\s+(.*)',line)
                if not m: continue
                fields=[t.split('=',1)[0] for t in m.group(1).split() if '=' in t]
                row=re.search(r'row=(\S+)',line)
                out[(f,row.group(1) if row else '?')]=fields
    return out
b=markers('ec816ca7'); a=markers('HEAD')
for k in sorted(set(b)|set(a)):
    fb,fa=b.get(k),a.get(k)
    if fb!=fa:
        print('DIFF',k)
        print('  before:',fb)
        print('  after :',fa)
    else:
        print('SAME field set',k,len(fa),'fields')
EOF
